class Solution{static class R{boolean ok;int n,lo,hi;R(boolean o,int n,int l,int h){ok=o;this.n=n;lo=l;hi=h;}}int b;R f(TreeNode x){if(x==null)return new R(true,0,Integer.MAX_VALUE,Integer.MIN_VALUE);R l=f(x.left),r=f(x.right);if(l.ok&&r.ok&&x.val>l.hi&&x.val<r.lo){R z=new R(true,l.n+r.n+1,l.n>0?l.lo:x.val,r.n>0?r.hi:x.val);b=Math.max(b,z.n);return z;}return new R(false,0,0,0);}public int largestBSTSubtree(TreeNode r){f(r);return b;}}
